legacyCss:
.h1-1 {margin:0;padding:0;}
#service-container { background-color:#f0eeec;}
#select_tools { font-size:15px;}
#select_tools .row{ display: flex; flex-wrap: wrap;}
#select_tools .row [class="col-"]{ display: flex; flex-direction: column;}
.form-control { background:none; border-left:0; border-right:0; border-top:0; border-bottom:2px solid #2789c0; border-radius:0; margin-top:10px; margin-bottom:10px; font-size:18px; box-shadow:none;}
.input_txt_1 { display:block; float:right;}
.service-txt { color:#FFF; font-size:16px; line-height:30px;}
.service-txt-b { font-weight:bold; font-size:28px;}
.service_spacing { padding-top:60px; padding-bottom:50px;}
.service_spacing-2 { padding-top:30px; padding-bottom:30px;}
#about-top-title {background-color:#008ecf; background-image:none;}
.service_block_bgcolor { background-color:#00334c;}
.AF_bg { color: #555; border-bottom:2px solid #15c0f3;}
#select_B { display:none;}
.btn_active { background-color:#15c0f3; color:#FFF;}
.btn_active a { color:#FFF;}
.setp_space_top { margin-top:15px;}
.setp_space_bottom { margin-bottom:15px;}
.step_unit { background:#15c0f3; color:#FFF; text-align:center; height:100px; width:100%; padding-left:5px; padding-right:5px; padding-top:20px; padding-bottom:20px; margin-bottom:10px; position: relative; border-radius:10px;}
.step_unit a { display:block; width:100%; height:100%;}
.step_unit p { position:absolute; display:block; font-size:22px; font-weight:bold; text-align:center; top:50%; left:50%; transform: translate(-50%, -50%);}
.step_style-1 { background:#2789c0; color:#FFF; text-align:center; font-size:28px; font-weight:bold; padding-left:15px; padding-right:15px; height:100%; width:100%;}
.step_style-1 p { position: relative; top:50%; transform:translateY(-50%);}
.step_style-2 { border:1px solid #2789c0; text-align:center; color:#2789c0;}
.step_style-3 { border:1px solid #2789c0; text-align:center; background-color:#FFF; height:100%; padding-bottom:25px;}
.step_bottom_border { border-bottom:1px solid #2789c0; font-size:28px; font-weight:bold;}
.select_btn a { text-decoration:none; font-size:28px;}
.step_arrow_down { padding-left:9%; padding-top:10px; padding-bottom:10px;}
.px-0 { padding-left:0; padding-right:0;}
.step4_txt_1 { font-size:24px;}
.step4_txt_2 { font-size:18px;}
.st_txt_style1 { padding-left: 15px; padding-right: 15px;}
@media (max-width: 767px) { #select_tools .row { display:block;}
.step_style-1 p { padding-top:15px; padding-bottom:15px; transform:none;}
.step_arrow_down { padding-left:0; text-align:center;}
}
